  <script>
    const cartCount = document.getElementById('cart-count');
    const cartButton = document.getElementById('cart-button');
    const filterStatus = document.getElementById('filter-status');
    const filterButtons = Array.from(document.querySelectorAll('[data-filter]'));
    const products = Array.from(document.querySelectorAll('#product-grid .card'));
    const addButtons = Array.from(document.querySelectorAll('.add-to-bag'));
    const countdown = {
      hours: document.getElementById('hours-left'),
      minutes: document.getElementById('minutes-left'),
      seconds: document.getElementById('seconds-left')
    };

    let cartTotal = 0;
    const dealEnd = (() => {
      const target = new Date();
      target.setHours(23, 59, 59, 999);
      return target;
    })();

    function formatValue(value) {
      return String(value).padStart(2, '0');
    }

    function updateCountdown() {
      const now = new Date();
      const remaining = Math.max(0, dealEnd - now);
      const seconds = Math.floor(remaining / 1000);
      const hours = Math.floor(seconds / 3600);
      const minutes = Math.floor((seconds % 3600) / 60);
      const secs = seconds % 60;

      countdown.hours.textContent = formatValue(hours);
      countdown.minutes.textContent = formatValue(minutes);
      countdown.seconds.textContent = formatValue(secs);
    }

    function setActiveFilter(filter) {
      filterButtons.forEach((button) => {
        const selected = button.dataset.filter === filter;
        button.setAttribute('aria-pressed', String(selected));
      });

      let visibleCount = 0;
      products.forEach((product) => {
        const matches = filter === 'all' || product.dataset.category === filter;
        product.hidden = !matches;
        if (matches) visibleCount += 1;
      });

      filterStatus.textContent =
        filter === 'all'
          ? 'Showing all featured products.'
          : `Showing ${visibleCount} featured product${visibleCount === 1 ? '' : 's'} in ${filter}.`;
    }

    filterButtons.forEach((button) => {
      button.addEventListener('click', () => setActiveFilter(button.dataset.filter));
    });

    addButtons.forEach((button) => {
      button.addEventListener('click', () => {
        cartTotal += 1;
        cartCount.textContent = String(cartTotal);
        cartButton.setAttribute('aria-label', `Shopping bag with ${cartTotal} item${cartTotal === 1 ? '' : 's'}`);
        filterStatus.textContent = `${button.dataset.product} added to your bag.`;
      });
    });

    setActiveFilter('all');
    updateCountdown();
    window.setInterval(updateCountdown, 1000);
  </script>
