      display: grid;
      place-items: center;
      background: linear-gradient(135deg, var(--accent) 0%, #b47b50 100%);
      color: #fff;
      box-shadow: 0 10px 24px #8b5e3c3d;
      flex: none;
    }

    .nav {
      display: flex;
      align-items: center;
      gap: 1.2rem;
      flex-wrap: wrap;
      justify-content: center;
    }

    .nav a {
      font-weight: 600;
      color: var(--muted);
      text-decoration: none;
    }

    .nav a:focus-visible,
    .nav a:hover {
      color: var(--text);
    }

    .utility {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .pill,
    .button {
      border: 1px solid var(--border);
      background: var(--surface);
      color: var(--text);
      border-radius: 999px;
      font: inherit;
      font-weight: 700;
      padding: 0.8rem 1.1rem;
      cursor: pointer;
      transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease;
    }

    .button--primary {
      border-color: transparent;
      background: var(--accent);
      color: #fff;
    }

    .button--primary:hover,
    .button--primary:focus-visible {
      background: var(--accent-strong);
    }

    .button:hover,
    .button:focus-visible,
    .pill:hover,
    .pill:focus-visible {
      transform: translateY(-1px);
      border-color: #bda98f;
      outline: none;
      box-shadow: 0 0 0 3px #c9996a33;
    }

    .cart {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
    }

    .cart-badge {
      min-width: 1.7rem;
      height: 1.7rem;
      padding-inline: 0.45rem;
      display: inline-grid;
      place-items: center;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent-strong);
      font-size: 0.92rem;
    }

    main {
      display: block;
    }

    .hero {
      padding: 3.2rem 0 2rem;
    }

    .hero-grid {
      display: grid;
      gap: 1.2rem;
      grid-template-columns: 1.2fr 0.8fr;
      align-items: stretch;
    }

    .hero-copy,
    .hero-visual,
    .panel,
    .card,
    .editorial-card {
      border: 1px solid var(--border);
      background: var(--surface);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      border-radius: var(--radius-xl);
      padding: clamp(1.5rem, 4vw, 3.2rem);
      display: grid;
      gap: 1.25rem;
      min-width: 0;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      width: fit-content;
      padding: 0.4rem 0.75rem;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent-strong);
      font-size: 0.92rem;
      font-weight: 700;
    }

    h1, h2, h3, p {
      margin: 0;
    }

    h1 {
      font-size: clamp(2.5rem, 6vw, 5rem);
      line-height: 0.95;
      letter-spacing: -0.04em;
      max-width: 12ch;
    }

    .hero-copy p {
      max-width: 58ch;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .cta-row {
      display: flex;
      gap: 0.85rem;
      flex-wrap: wrap;
    }

    .hero-metrics {
      display: grid;
      gap: 0.9rem;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      margin-top: 0.2rem;
    }

    .metric {
      padding: 1rem;
      border-radius: var(--radius-md);
      background: #f9f7f3;
      border: 1px solid #e6decf;
      min-width: 0;
    }

    .metric strong {
      display: block;
      font-size: 1.2rem;
      margin-bottom: 0.25rem;
    }

    .metric span {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .hero-visual {
      border-radius: var(--radius-xl);
      padding: 1.2rem;
      display: grid;
      gap: 1rem;
      align-content: space-between;
      background:
        radial-gradient(circle at top right, #f8dfcc 0, transparent 35%),
        linear-gradient(180deg, #fff 0%, #faf6f0 100%);
      min-width: 0;
    }

    .visual-stage {
      min-height: 360px;
      border-radius: calc(var(--radius-xl) - 6px);
      background:
        linear-gradient(135deg, #f7e8da 0%, #efd8c2 35%, #d7a57d 100%);
      padding: 1rem;
      display: grid;
      align-content: end;
      position: relative;
      overflow: hidden;
    }

    .visual-stage::before,
    .visual-stage::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: #fff7ef;
    }

    .visual-stage::before {
      width: 170px;
      height: 170px;
      top: -30px;
      right: -20px;
    }

    .visual-stage::after {
      width: 115px;
      height: 115px;
      left: 28px;
      bottom: 70px;
      background: #f2d2ba;
    }

    .visual-card {
      position: relative;
      z-index: 1;
      width: min(100%, 230px);
      padding: 1rem;
      border-radius: 22px;
      background: #ffffffea;
      border: 1px solid #ffffff;
      box-shadow: 0 18px 32px #6c46212b;
      display: grid;
      gap: 0.75rem;
    }

    .visual-card strong {
      font-size: 1.05rem;
    }

    .visual-tag {
      justify-self: start;
      padding: 0.36rem 0.7rem;
      border-radius: 999px;
      background: #1c1c1c;
      color: #fff;
      font-size: 0.85rem;
      font-weight: 700;
    }

    .section {
      padding: 2rem 0;
    }

    .section-header {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-header p {
      color: var(--muted);
      max-width: 58ch;
    }

    .toolbar {
      display: flex;
      gap: 0.6rem;
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    .toolbar .pill[aria-pressed="true"] {
      background: var(--text);
      color: #fff;
      border-color: var(--text);
    }

    .panel {
      border-radius: var(--radius-xl);
      padding: 1.1rem;
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .card {
      border-radius: 24px;
      padding: 1rem;
      display: grid;
      gap: 0.9rem;
      min-width: 0;
    }

    .product-art {
      min-height: 180px;
      border-radius: 18px;
      background:
        linear-gradient(145deg, #f8efe6 0%, #ecd4be 48%, #d7aa80 100%);
      display: grid;
      place-items: end start;
      padding: 1rem;
      position: relative;
      overflow: hidden;
    }

    .product-art::before {
      content: "";
      position: absolute;
      inset: auto 18px 18px auto;
      width: 110px;
      height: 110px;
      border-radius: 32px 32px 44px 44px;
      background: #fff9f3;
      box-shadow: inset 0 -10px 0 #f0ddc7;
      transform: rotate(10deg);
    }

    .product-art::after {
      content: "";
      position: absolute;
      left: 24px;
      top: 26px;
      width: 66px;
      height: 66px;
      border-radius: 50%;
      background: #936340;
      box-shadow: 54px 52px 0 0 #f5e3d0;
    }

    .product-art--2 {
      background: linear-gradient(145deg, #eef3f1 0%, #cee0d9 48%, #8da995 100%);
    }

    .product-art--2::after {
      background: #224d3d;
      box-shadow: 54px 52px 0 0 #e8f1ec;
    }

    .product-art--3 {
      background: linear-gradient(145deg, #f7f0ea 0%, #f0d0c3 55%, #b87d66 100%);
    }

    .product-art--3::after {
      background: #7a4638;
      box-shadow: 54px 52px 0 0 #f6e8e0;
    }

    .product-art--4 {
      background: linear-gradient(145deg, #f4f0f9 0%, #dcd0ef 52%, #9f84cc 100%);
    }

    .product-art--4::after {
      background: #5f459a;
      box-shadow: 54px 52px 0 0 #f0ecf8;
    }

    .product-meta {
      display: flex;
      justify-content: space-between;
      gap: 0.5rem;
      align-items: center;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .price {
      font-weight: 800;
      color: var(--text);
      font-size: 1.15rem;
    }

    .card h3 {
      font-size: 1.1rem;
      line-height: 1.2;
    }

    .card p {
      color: var(--muted);
      font-size: 0.96rem;
    }

    .card-actions {
      display: flex;
      gap: 0.7rem;
      align-items: center;
      flex-wrap: wrap;
    }

    .card-actions .button {
      flex: 1 1 0;
      justify-content: center;
    }

    .subtle {
      color: var(--muted);
      font-size: 0.94rem;
    }

    .deal-grid {
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: 1rem;
    }

    .deal-banner {
      border-radius: var(--radius-xl);
      padding: clamp(1.2rem, 3vw, 2rem);
      background:
        linear-gradient(135deg, #1f1b18 0%, #43362d 100%);
      color: #fff;
      display: grid;
      gap: 1rem;
      min-width: 0;
      box-shadow: var(--shadow);
    }

    .deal-banner p,
    .deal-card p {
      color: inherit;
    }

    .deal-grid .deal-banner .button--primary {
      background: #f7eadf;
      color: #1f1b18;
    }

    .deal-grid .deal-banner .button--primary:hover,
    .deal-grid .deal-banner .button--primary:focus-visible {
      background: #ffffff;
    }

    .countdown {
      display: inline-flex;
      gap: 0.6rem;
      flex-wrap: wrap;
    }

    .countdown .metric {
      background: #ffffff12;
      border-color: #ffffff26;
      color: #fff;
      min-width: 5.5rem;
    }

    .countdown .metric span {
      color: #f1ebe5;
    }

    .deal-card {
      border-radius: var(--radius-xl);
      padding: 1.2rem;
      background: var(--surface);
      border: 1px solid var(--border);
      box-shadow: var(--shadow);
      display: grid;
      gap: 1rem;
      min-width: 0;
    }

    .deal-card--accent {
      background: linear-gradient(180deg, #fff 0%, #f8f0e7 100%);
    }

    .deal-card .button {
      justify-self: start;
    }

    .editorial-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .editorial-card {
      border-radius: var(--radius-xl);
      overflow: hidden;
      display: grid;
      min-width: 0;
    }

    .editorial-art {
      min-height: 200px;
      background:
        radial-gradient(circle at 20% 25%, #fff8ef 0 8%, transparent 9%),
        linear-gradient(145deg, #f1ddcc 0%, #d7b297 100%);
    }

    .editorial-art--2 {
      background:
        radial-gradient(circle at 72% 20%, #edf6f0 0 9%, transparent 10%),
        linear-gradient(145deg, #dde8e0 0%, #a5b8ad 100%);
    }

    .editorial-art--3 {
      background:
        radial-gradient(circle at 30% 26%, #f5e6ef 0 9%, transparent 10%),
        linear-gradient(145deg, #e0cee5 0%, #b497c2 100%);
    }

    .editorial-body {
      padding: 1rem;
      display: grid;
      gap: 0.75rem;
    }

    .editorial-body h3 {
      font-size: 1.1rem;
    }

    .editorial-body p {
      color: var(--muted);
    }

    .editorial-body a {
      width: fit-content;
      font-weight: 700;
    }

    .status {
      margin-top: 0.75rem;
      min-height: 1.5rem;
      color: var(--success);
      font-weight: 700;
    }

    .footer {
      padding: 2rem 0 3rem;
      color: var(--muted);
    }

    .footer-inner {
      border-top: 1px solid var(--border);
      padding-top: 1.4rem;
      display: flex;
      gap: 1rem;
      justify-content: space-between;
      flex-wrap: wrap;
    }

    :focus-visible {
      outline: 3px solid #2a221a;
      outline-offset: 3px;
    }

    [hidden] {
      display: none !important;
    }

    @media (max-width: 980px) {
      .hero-grid,
      .deal-grid,
      .editorial-grid,
      .product-grid {
        grid-template-columns: 1fr 1fr;
      }

      .hero-grid,
      .deal-grid {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 720px) {
      .topbar .shell,
      .section-header {
        flex-direction: column;
        align-items: start;
      }

      .nav,
      .utility,
      .toolbar {
        justify-content: flex-start;
      }

      .hero-metrics,
      .product-grid,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .cta-row,
      .card-actions {
        flex-direction: column;
        align-items: stretch;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-strong: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --border: ButtonBorder;
        --accent: Highlight;
        --accent-strong: HighlightText;
        --accent-soft: Canvas;
      }

      .topbar,
      .hero-copy,
      .hero-visual,
      .panel,
      .card,
      .editorial-card,
      .deal-banner,
      .deal-card {
        box-shadow: none;
      }

      .brand-mark,
      .visual-stage::before,
      .visual-stage::after,
      .product-art::before,
      .product-art::after,
      .product-art--2::after,
      .product-art--3::after,
      .product-art--4::after,
      .editorial-art,
      .editorial-art--2,
      .editorial-art--3 {
        forced-color-adjust: auto;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <header class="topbar">
    <div class="shell">
      <a class="brand" href="#" aria-label="Northstar Market home">
        <span class="brand-mark" aria-hidden="true">N</span>
        Northstar Market
      </a>

      <nav aria-label="Primary">
        <ul class="nav">
          <li><a href="#featured">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#stories">Stories</a></li>
        </ul>
      </nav>

      <div class="utility">
        <button class="pill cart" type="button" id="cart-button" aria-label="Shopping bag with 0 items">
          Bag <span class="cart-badge" id="cart-count" aria-hidden="true">0</span>
        </button>
        <a class="button button--primary" href="#featured">Shop now</a>
      </div>
    </div>
  </header>

  <main id="main-content">
    <section class="hero">
      <div class="shell">
        <div class="hero-grid">
          <div class="hero-copy">
            <span class="eyebrow">New season arrival</span>
            <h1>Retail essentials with a calm, modern point of view.</h1>
            <p>
              Discover refined home goods, everyday wear, and editor-approved picks designed to look
              sharp, feel practical, and make the shelf feel curated.
            </p>
            <div class="cta-row">
              <a class="button button--primary" href="#featured">Browse featured products</a>
              <a class="button" href="#stories">Read the lookbook</a>
            </div>
            <div class="hero-metrics" aria-label="Store highlights">
              <div class="metric">
                <strong>2-day</strong>
                <span>shipping on most orders</span>
              </div>
              <div class="metric">
                <strong>4.8/5</strong>
                <span>average customer rating</span>
              </div>
              <div class="metric">
                <strong>Free</strong>
                <span>returns on every purchase</span>
              </div>
            </div>
          </div>

          <aside class="hero-visual" aria-label="Featured product preview">
            <div class="visual-stage" aria-hidden="true">
              <div class="visual-card">
                <span class="visual-tag">Best seller</span>
                <strong>Studio Carry Tote</strong>
                <span class="subtle">$68 in warm clay</span>
              </div>
            </div>
            <p class="subtle">Thoughtful textures, easy neutrals, and a premium finish across every category.</p>
          </aside>
        </div>
      </div>
    </section>

    <section class="section" id="featured">
      <div class="shell">
        <div class="section-header">
          <div>
            <h2>Featured products</h2>
            <p>Four polished picks across home, travel, and lifestyle essentials.</p>
          </div>
          <div class="toolbar" role="toolbar" aria-label="Filter featured products">
            <button class="pill" type="button" data-filter="all" aria-pressed="true">All</button>
            <button class="pill" type="button" data-filter="home" aria-pressed="false">Home</button>
            <button class="pill" type="button" data-filter="travel" aria-pressed="false">Travel</button>
            <button class="pill" type="button" data-filter="style" aria-pressed="false">Style</button>
          </div>
        </div>

        <div class="panel">
          <div class="product-grid" id="product-grid">
            <article class="card" data-category="home">
              <div class="product-art" aria-hidden="true"></div>
              <div class="product-meta">
                <span>Home</span>
                <span>4.9 ★</span>
              </div>
              <h3>Stoneware Morning Set</h3>
              <p>Stackable cups and plates with a soft matte glaze and warm-toned finish.</p>
              <div class="card-actions">
                <span class="price">$42</span>
                <button class="button add-to-bag" type="button" data-product="Stoneware Morning Set">Add to bag</button>
              </div>
            </article>

            <article class="card" data-category="travel">
              <div class="product-art product-art--2" aria-hidden="true"></div>
              <div class="product-meta">
                <span>Travel</span>
                <span>4.8 ★</span>
              </div>
              <h3>Carry-On Organizer</h3>
              <p>Lightweight packing cubes that keep essentials tidy from departure to arrival.</p>
              <div class="card-actions">
                <span class="price">$36</span>
                <button class="button add-to-bag" type="button" data-product="Carry-On Organizer">Add to bag</button>
              </div>
            </article>

            <article class="card" data-category="style">
              <div class="product-art product-art--3" aria-hidden="true"></div>
              <div class="product-meta">
                <span>Style</span>
                <span>4.9 ★</span>
              </div>
              <h3>Everyday Knit Jacket</h3>
              <p>Relaxed layering with a clean silhouette and a textured finish.</p>
              <div class="card-actions">
                <span class="price">$88</span>
                <button class="button add-to-bag" type="button" data-product="Everyday Knit Jacket">Add to bag</button>
              </div>
            </article>

            <article class="card" data-category="home">
              <div class="product-art product-art--4" aria-hidden="true"></div>
              <div class="product-meta">
                <span>Home</span>
                <span>4.7 ★</span>
              </div>
              <h3>Ambient Table Lamp</h3>
              <p>Soft directional light in a compact shape made for desks and side tables.</p>
              <div class="card-actions">
                <span class="price">$74</span>
                <button class="button add-to-bag" type="button" data-product="Ambient Table Lamp">Add to bag</button>
              </div>
            </article>
          </div>
          <div class="status" id="filter-status" aria-live="polite">Showing all featured products.</div>
        </div>
      </div>
    </section>

    <section class="section" id="deals">
      <div class="shell">
        <div class="section-header">
          <div>
            <h2>Deals</h2>
            <p>Limited-time offers selected to feel special without overwhelming the page.</p>
          </div>
        </div>

        <div class="deal-grid">
          <article class="deal-banner">
            <span class="eyebrow">48-hour event</span>
            <h3 style="font-size: clamp(1.7rem, 3vw, 2.6rem); line-height: 1.05; max-width: 12ch;">Save on the edit everyone is talking about.</h3>
            <p>Use code <strong>EDIT15</strong> for 15% off home and travel favorites through the end of the weekend.</p>
            <div class="countdown" aria-label="Deal countdown">
              <div class="metric">
                <strong id="hours-left">--</strong>
                <span>hours</span>
              </div>
              <div class="metric">
                <strong id="minutes-left">--</strong>
                <span>minutes</span>
              </div>
              <div class="metric">
                <strong id="seconds-left">--</strong>
                <span>seconds</span>
              </div>
            </div>
            <a class="button button--primary" href="#featured">Shop the deal</a>
          </article>

          <article class="deal-card deal-card--accent">
            <span class="eyebrow">Bundle offer</span>
            <h3>Complete the desk setup</h3>
            <p>Pair the Ambient Table Lamp with storage accessories and save 20% when you buy two or more.</p>
            <a class="button" href="#featured">Build a bundle</a>
          </article>
        </div>
      </div>
    </section>

    <section class="section" id="stories">
      <div class="shell">
        <div class="section-header">
          <div>
            <h2>Editorial content</h2>
            <p>Short-form inspiration that helps shoppers imagine how products live in a real space.</p>
          </div>
        </div>

        <div class="editorial-grid">
          <article class="editorial-card">
            <div class="editorial-art" aria-hidden="true"></div>
            <div class="editorial-body">
              <span class="eyebrow">Style notes</span>
              <h3>How to build a calm neutral palette</h3>
              <p>Layer texture, not just color, to keep a minimalist room from feeling flat.</p>
              <a href="#featured">Read the guide</a>
            </div>
          </article>

          <article class="editorial-card">
            <div class="editorial-art editorial-art--2" aria-hidden="true"></div>
            <div class="editorial-body">
              <span class="eyebrow">In the bag</span>
              <h3>Travel pieces that earn their space</h3>
              <p>Smart organizers and lightweight layers that make every trip feel easier.</p>
              <a href="#featured">See the picks</a>
            </div>
          </article>

          <article class="editorial-card">
            <div class="editorial-art editorial-art--3" aria-hidden="true"></div>
            <div class="editorial-body">
              <span class="eyebrow">New arrival</span>
              <h3>Meet the newest home accent collection</h3>
              <p>Small objects with sculptural form, soft edges, and easy-to-style finishes.</p>
              <a href="#featured">Explore the drop</a>
            </div>
          </article>
        </div>
      </div>
    </section>
  </main>

  <footer class="footer">
    <div class="shell">
      <div class="footer-inner">
